/**
 * RKplex — Apple Music style quality marks merged into album + player UI.
 * Uses Lossless / Hi-Res Lossless logos (not clear-logo / Hi-Res AUDIO artwork).
 */
(function () {
  const STYLE_ID = "rk-apple-music-ui";
  const IMAGES = {"lossless": "data:image/png;base64,", "hires_lossless": "data:image/png;base64,", "hires": "data:image/png;base64,"};
  const QUALITY_RE = /\s*\[(?:Hi-Res\s*Lossless|Hi-Res|Lossless)\]\s*/gi;

  const css = `
  /* Kill Jellyfin clear-logo slot that showed the big gold Hi-Res AUDIO artwork */
  .itemDetailPage.rk-music-page .detailLogo,
  .itemDetailPage .detailLogo[src*="Logo"],
  .detailPagePrimaryContainer .detailLogo {
    display: none !important;
  }

  .rk-apple-badge {
    display: inline-flex !important;
    align-items: center;
    vertical-align: middle;
    height: 22px;
    width: auto;
    margin: .45rem .35rem .15rem 0;
    filter: drop-shadow(0 2px 8px rgba(0,0,0,.35));
    pointer-events: none;
    user-select: none;
  }
  .detailPagePrimaryContainer .rk-apple-badge,
  .nameContainer .rk-apple-badge,
  .itemDetailPage .rk-apple-badge {
    height: 28px;
    margin: .55rem 0 .1rem;
  }
  .rk-apple-badge-row {
    display: flex;
    align-items: center;
    gap: .35rem;
    margin-top: .35rem;
  }

  /* Cards: small corner pill */
  .cardBox .rk-apple-badge {
    position: absolute;
    left: .4rem;
    bottom: .4rem;
    z-index: 6;
    height: 18px;
    margin: 0;
  }

  /* Now Playing bar + full player */
  .nowPlayingBar .rk-apple-badge,
  .appfooter .rk-apple-badge,
  .nowPlayingBarSecondaryText .rk-apple-badge {
    height: 16px;
    margin: 0 0 0 .4rem;
  }
  .nowPlayingPage .rk-apple-badge,
  .playlistSection .rk-apple-badge,
  .nowPlayingInfoContainer .rk-apple-badge {
    height: 20px;
    margin: .25rem 0 0;
  }
  .rk-np-meta {
    display: inline-flex;
    align-items: center;
    flex-wrap: wrap;
    gap: .35rem;
  }

  /* Movie-like blurred backdrop from cover */
  .itemDetailPage.rk-music-page .detailPagePrimaryContainer {
    position: relative;
    overflow: hidden;
  }
  .rk-music-backdrop {
    position: absolute !important;
    inset: 0;
    z-index: 0;
    pointer-events: none;
    overflow: hidden;
  }
  .rk-music-backdrop img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    filter: blur(48px) saturate(1.3) brightness(.5);
    transform: scale(1.2);
    opacity: .95;
  }
  .rk-music-backdrop::after {
    content: "";
    position: absolute;
    inset: 0;
    background: linear-gradient(180deg, rgba(0,0,0,.2) 0%, rgba(0,0,0,.55) 40%, rgba(0,0,0,.92) 100%);
  }
  .itemDetailPage.rk-music-page .detailPageContent,
  .itemDetailPage.rk-music-page .detailPagePrimaryContainer > *:not(.rk-music-backdrop),
  .itemDetailPage.rk-music-page .detailSection {
    position: relative;
    z-index: 1;
  }

  /* Hide leftover custom text chips */
  .rk-qbadge:not(img), .rk-hires-audio-badge { display: none !important; }
`;

  function ensureStyle() {
    let style = document.getElementById(STYLE_ID);
    if (!style) {
      style = document.createElement("style");
      style.id = STYLE_ID;
      document.head.appendChild(style);
    }
    style.textContent = css;
  }

  function detectQuality(text) {
    const t = (text || "").toLowerCase();
    if (t.includes("hi-res lossless") || t.includes("hires lossless")) return "hires_lossless";
    if (t.includes("[hi-res]") || /\bhi-?res\b/.test(t)) return "hires_lossless";
    if (t.includes("lossless") || /\bflac\b/.test(t)) return "lossless";
    return null;
  }

  function qualityFromStreams(streams) {
    if (!streams || !streams.length) return null;
    const a = streams.find((s) => (s.Type || s.type) === "Audio") || streams[0];
    const bits = Number(a.BitDepth || a.bitDepth || 0);
    const rate = Number(a.SampleRate || a.sampleRate || 0);
    const codec = String(a.Codec || a.codec || "").toLowerCase();
    const lossless = /flac|alac|pcm|wav|aiff|dsd/.test(codec) || bits >= 16;
    if (!lossless && !bits && !rate) return null;
    if (bits >= 24 && rate > 48000) return "hires_lossless";
    if (bits >= 24 || rate > 48000) return "hires_lossless";
    if (lossless || bits >= 16) return "lossless";
    return null;
  }

  function makeBadge(kind, cls) {
    const img = document.createElement("img");
    img.className = "rk-apple-badge " + (cls || "");
    img.alt = kind === "lossless" ? "Lossless" : "Hi-Res Lossless";
    img.draggable = false;
    img.src = IMAGES[kind] || IMAGES.lossless;
    img.dataset.rkKind = kind;
    return img;
  }

  function cleanQualityText(el) {
    if (!el || el.dataset.rkCleaned === "1") return;
    const raw = (el.textContent || "").trim();
    if (!QUALITY_RE.test(raw)) return;
    QUALITY_RE.lastIndex = 0;
    el.dataset.rkCleaned = "1";
    el.dataset.rkOriginal = raw;
    el.setAttribute("title", raw);
    el.textContent = raw.replace(QUALITY_RE, " ").replace(/\s{2,}/g, " ").trim();
  }

  function upsertBadge(host, kind, cls) {
    if (!host || !kind) return;
    let img = host.querySelector(":scope > .rk-apple-badge, .rk-apple-badge");
    // Prefer a dedicated row under titles on detail pages
    if (!img) {
      img = makeBadge(kind, cls);
      host.appendChild(img);
    } else if (img.dataset.rkKind !== kind) {
      img.src = IMAGES[kind] || IMAGES.lossless;
      img.dataset.rkKind = kind;
      img.alt = kind === "lossless" ? "Lossless" : "Hi-Res Lossless";
    }
  }

  function cardText(card) {
    const parts = [];
    card.querySelectorAll(".cardText, .cardText-first, .cardText-secondary, .itemText, button[title], a[title]").forEach((n) => {
      parts.push(n.textContent || "", n.getAttribute("title") || "");
    });
    parts.push(card.getAttribute("title") || "", card.getAttribute("aria-label") || "");
    return parts.join(" ");
  }

  function decorateCards(root) {
    root.querySelectorAll(".card, .cardBox").forEach((card) => {
      if (card.querySelector(".rk-apple-badge")) return;
      const q = detectQuality(cardText(card));
      if (!q) return;
      const host = card.classList.contains("cardBox") ? card : card.querySelector(".cardBox") || card;
      host.style.position = host.style.position || "relative";
      host.appendChild(makeBadge(q));
    });
  }

  function enhanceBackdrop(page) {
    page.classList.add("rk-music-page");
    if (page.querySelector(".rk-music-backdrop")) return;
    const cover =
      page.querySelector(".detailImageContainer img, .detailPortrait img, .itemPrimaryImage img") ||
      page.querySelector("img.itemDetailImage, img.detailImage");
    if (!cover || !cover.src) return;
    const wrap = document.createElement("div");
    wrap.className = "rk-music-backdrop";
    const img = document.createElement("img");
    img.alt = "";
    img.src = cover.src;
    wrap.appendChild(img);
    const host = page.querySelector(".detailPagePrimaryContainer") || page.querySelector(".detailPageWrapperContainer") || page;
    host.style.position = host.style.position || "relative";
    host.insertBefore(wrap, host.firstChild);
  }

  function decorateDetail() {
    const page = document.querySelector(".itemDetailPage");
    if (!page) return;
    enhanceBackdrop(page);

    // Always hide clear logos on music pages
    page.querySelectorAll(".detailLogo").forEach((n) => { n.style.display = "none"; });

    const title =
      page.querySelector(".itemName.originalTitle, .nameContainer .itemName, h1.itemName, .itemName") ||
      page.querySelector(".detailPagePrimaryContainer .itemName");
    if (!title) return;

    const secondary = page.querySelector(".itemName.parentNameLastAligned, .parentName, .detail-secondary, .nameContainer a");
    const blob = [title.textContent, title.getAttribute("title"), secondary && secondary.textContent, document.title]
      .filter(Boolean)
      .join(" ");
    const q = detectQuality(blob) || detectQuality(location.hash);
    cleanQualityText(title);

    if (!q) return;

    // Place badge under title block (Apple Music style), not as detailLogo artwork
    let row = page.querySelector(".rk-apple-badge-row");
    if (!row) {
      row = document.createElement("div");
      row.className = "rk-apple-badge-row";
      const parent = title.parentElement || title;
      parent.insertBefore(row, title.nextSibling);
    }
    upsertBadge(row, q);
  }

  async function apiQualityFromPlaying() {
    try {
      if (!window.ApiClient) return null;
      const info = (window.MediaController && window.MediaController.currentMediaSource) || null;
      // Prefer playback manager
      const pm = window.PlaybackManager || window.playbackManager;
      let item = null;
      if (pm && typeof pm.currentItem === "function") item = pm.currentItem();
      else if (pm && pm._currentPlayer && pm._currentPlayer._currentItem) item = pm._currentPlayer._currentItem;
      if (!item && window.MediaController && MediaController.currentItem) item = MediaController.currentItem;
      if (!item || !item.Id) {
        // Fallback: parse now playing DOM text only
        return null;
      }
      // MediaStreams may already be on item
      let streams = item.MediaStreams;
      if (!streams) {
        const full = await ApiClient.getItem(ApiClient.getCurrentUserId(), item.Id);
        streams = full && full.MediaStreams;
        if (full && full.Album) item._albumName = full.Album;
      }
      const fromStreams = qualityFromStreams(streams);
      if (fromStreams) return fromStreams;
      const nameBlob = [item.Name, item.Album, item.AlbumArtist, item._albumName, item.Path].filter(Boolean).join(" ");
      return detectQuality(nameBlob);
    } catch (e) {
      return null;
    }
  }

  function decorateNowPlaying(forcedKind) {
    const bar = document.querySelector(".nowPlayingBar, .appfooter");
    const secondary =
      document.querySelector(".nowPlayingBarSecondaryText") ||
      document.querySelector(".nowPlayingBarInfo .secondaryText") ||
      document.querySelector(".nowPlayingSongName") ||
      document.querySelector(".nowPlayingBarText");

    // Full now-playing / queue header (screenshot 2)
    const headers = document.querySelectorAll(
      ".nowPlayingPage .nowPlayingInfoContainer, .playlistSection .flex.align-items-center, .nowPlayingInfoControls"
    );

    const textBlob = [
      secondary && (secondary.dataset.rkOriginal || secondary.textContent),
      bar && bar.textContent,
      document.title,
    ]
      .filter(Boolean)
      .join(" ");

    const q = forcedKind || detectQuality(textBlob);
    if (secondary) cleanQualityText(secondary);

    // Also clean any visible [Hi-Res] in now playing context
    document.querySelectorAll(".nowPlayingBarSecondaryText, .nowPlayingBarText, .listItemBodyText").forEach((el) => {
      if (/\[Hi-Res/i.test(el.textContent || "")) cleanQualityText(el);
    });

    if (!q) return;

    if (secondary) {
      // Keep badge inline with album line
      if (!secondary.parentElement.classList.contains("rk-np-meta")) {
        // wrap not always safe; append badge after secondary
      }
      let host = secondary.parentElement;
      if (host && !host.querySelector(".rk-apple-badge")) {
        upsertBadge(host, q);
      } else if (host) {
        upsertBadge(host, q);
      } else {
        upsertBadge(secondary, q);
      }
    }

    if (bar && !bar.querySelector(".rk-apple-badge") && secondary) {
      // already handled via secondary parent
    }

    // Player page title area
    document.querySelectorAll(".nowPlayingPage .itemName, .nowPlayingPage .secondaryText, .nowPlayingInfoContainer").forEach((el) => {
      cleanQualityText(el);
      if (!el.querySelector(".rk-apple-badge") && q) {
        // only attach to containers, not every text node
        if (el.classList.contains("nowPlayingInfoContainer") || el.classList.contains("secondaryText")) {
          upsertBadge(el, q);
        }
      }
    });
  }

  let _pendingApi = false;
  async function refreshFromApi() {
    if (_pendingApi) return;
    _pendingApi = true;
    try {
      const q = await apiQualityFromPlaying();
      if (q) decorateNowPlaying(q);
    } finally {
      _pendingApi = false;
    }
  }

  function run() {
    ensureStyle();
    decorateCards(document);
    decorateDetail();
    decorateNowPlaying();
  }

  ensureStyle();
  run();
  refreshFromApi();

  const obs = new MutationObserver(() => {
    run();
  });
  obs.observe(document.documentElement, { childList: true, subtree: true });
  setInterval(() => {
    run();
    refreshFromApi();
  }, 2500);

  // Hook play events when available
  document.addEventListener("viewshow", () => { run(); refreshFromApi(); });
  window.addEventListener("hashchange", () => { setTimeout(() => { run(); refreshFromApi(); }, 200); });
})();
